package main

import (
	"fmt"
	"io/ioutil"
	"os"

	"golang.org/x/tools/imports"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file_name> <struct_name>")
		return
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	// Import the Avro package if it's not already imported
	if !imports.IsImported(sourceFileName, "github.com/tendermint/go-avro") {
		imports.ImportAll(sourceFileName, "github.com/tendermint/go-avro")
	}

	// Read the Go source code into memory
	content, err := ioutil.ReadFile(sourceFileName)
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		return
	}

	// Generate the Avro schema string
	schemaString, err := imports.GenAvroSchema(structName, content)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	// Write the generated Avro schema to a file
	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), []byte(schemaString), 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema file: %v\n", err)
		return
	}
	fmt.Printf("Generated Avro schema saved to %s.avsc\n", structName)
}
